<main class="content container-fluid"><section class="welcome-card p-4 p-lg-5 mb-5"><div class="row align-items-center g-4"><div class="col-lg-9"><span class="eyebrow text-warning">ÁREA DOCENTE</span><h2 class="display-title mt-2 mb-2">Hola, <?=e($user['first_name'])?>. Tu ruta de aprendizaje está lista.</h2><p class="mb-0 text-white-50">Asignatura: <strong class="text-white"><?=e($user['subject']??'General')?></strong></p></div><div class="col-lg-3 text-lg-end"><a class="btn btn-light btn-lg" href="<?=url('/docente/perfil')?>">Actualizar mis datos</a></div></div></section><?php foreach([['Tests disponibles',$tests,$user['test_enabled'],'test'],['Tabuladores',$tabulators,$user['tabulator_enabled'],'tabulador']] as [$label,$items,$enabled,$type]):?><section class="mb-5"><div class="d-flex align-items-center justify-content-between mb-3"><h2 class="h3 mb-0"><?=$label?></h2><span class="badge badge-soft-purple rounded-pill"><?=count($items)?> recursos</span></div><?php if(!$enabled):?><div class="empty-state">Este módulo aún no está habilitado en tu perfil.</div><?php elseif(!$items):?><div class="empty-state">No hay recursos publicados para tu asignatura.</div><?php else:?><div class="row g-4"><?php foreach($items as $r):?><div class="col-md-6 col-xl-4"><article class="card teacher-resource h-100"><div class="card-body p-4"><span class="resource-icon mb-3"><?=$type==='test'?'✓':'▦'?></span><span class="resource-meta"><?=e(strtoupper($type))?></span><h3 class="h5 mt-2"><?=e($r['name'])?></h3><p class="text-secondary"><?=e($r['description'])?></p><div class="d-flex flex-wrap gap-2 mt-auto"><?php if($r['file_path']):?><a class="btn btn-sm btn-brand" href="<?=url('/docente/descargar?id='.$r['id'])?>">Descargar archivo ↓</a><?php endif;?><?php if($r['external_link']):?><a class="btn btn-sm btn-outline-primary" href="<?=e($r['external_link'])?>" target="_blank" rel="noopener">Abrir enlace ↗</a><?php endif;?></div></div></article></div><?php endforeach;?></div><?php endif;?></section><?php endforeach;?></main>
